 const safe=track?runtime.beginSafeChange('service-port',id,`${service.name}-poort ${service.port} → ${port}`,{port:service.port,status:service.status},{port}):undefined;
 if(safe)runtime.updateOperation(safe.operationId,18,'Momentopname van poort en servicestatus vastgelegd.',{index:0,status:'ok',detail:`Poort ${service.port}; status ${service.status}.`});
 const current=await runtime.inspectPort(id),simulation=before.settings.simulationMode,windowsService=before.settings.runtimeMode==='windows-service'&&!simulation,wasRunning=current.status==='localdeck'||simulation&&service.status==='running',stopped:ServiceId[]=[];
