async function runMailQuality(){const operationId=runtime.beginOperation('mail-quality','Mail Quality Lab',{steps:['Mailpit gereedmaken','Laatste bericht lezen','Inhoud beoordelen','Rapport opslaan']});try{await ensureService('mail');runtime.updateOperation(operationId,24,'Mailpit is bereikbaar.',{index:0,status:'ok',detail:'Alleen de lokale inbox wordt gelezen.'});const port=runtime.snapshot().services.find(item=>item.id==='mail')?.port??8025,response=await fetch(`http://127.0.0.1:${port}/api/v1/messages?limit=1`,{signal:AbortSignal.timeout(8000)});if(!response.ok)throw new Error(`Mailpit API antwoordt met HTTP ${response.status}.`);const payload=await response.json()as{messages?:Array<{Subject?:string;Snippet?:string;From?:{Address?:string};To?:Array<{Address?:string}>;Attachments?:number}>},message=payload.messages?.[0],checks:EngineeringCheck[]=[];runtime.updateOperation(operationId,48,'Laatste bericht gelezen.',{index:1,status:message?'ok':'warning',detail:message?.Subject||'Inbox is leeg.'});if(message){const subject=String(message.Subject||''),snippet=String(message.Snippet||''),from=String(message.From?.Address||''),to=message.To?.map(item=>item.Address).filter(Boolean)??[];checks.push({id:'subject',label:'Onderwerp',status:subject.trim().length>=4?'ok':'warning',detail:subject||'Onderwerp ontbreekt.'},{id:'sender',label:'Afzender',status:/^[^@\s]+@[^@\s]+$/.test(from)?'ok':'warning',detail:from||'Afzender ontbreekt.'},{id:'recipient',label:'Ontvangers',status:to.length?'ok':'error',detail:to.length?to.join(', '):'Geen ontvanger.'},{id:'content',label:'Berichtinhoud',status:snippet.trim().length>=20?'ok':'warning',detail:`Preview bevat ${snippet.length} tekens.`},{id:'attachments',label:'Bijlagen',status:'ok',detail:`${message.Attachments||0} bijlagen.`})}else checks.push({id:'inbox',label:'Testbericht',status:'warning',detail:'Stuur eerst een testmail om inhoud en adressen te analyseren.'});runtime.updateOperation(operationId,80,'Inhoud en adressen beoordeeld.',{index:2,status:checks.some(item=>item.status==='error')?'error':checks.some(item=>item.status==='warning')?'warning':'ok',detail:`${checks.filter(item=>item.status==='ok').length}/${checks.length} controles geslaagd.`});runtime.updateOperation(operationId,95,'Mailrapport opslaan…',{index:3,status:'ok',detail:'Geen berichtinhoud buiten deze computer verzonden.'});return runtime.recordExternalReport('mail-quality',{title:'Mail Quality Lab',summary:message?`${checks.filter(item=>item.status==='ok').length}/${checks.length} kwaliteitscontroles geslaagd.`:'Inbox is leeg; stuur een testbericht.',checks,metrics:{messages:message?1:0}},operationId)}catch(error){const message=error instanceof Error?error.message:String(error);runtime.completeOperation(operationId,message,'failed');throw error}}
async function runApiRequest(workspaceId:string,endpointId:string,body:string){const workspace=runtime.snapshot().apiWorkspaces.find(item=>item.id===workspaceId),endpoint=workspace?.endpoints.find(item=>item.id===endpointId);if(!workspace||!endpoint)throw new Error('API-endpoint niet gevonden.');const url=new URL(endpoint.path.replace(/\{[^}]+\}/g,'1'),`${workspace.baseUrl.replace(/\/$/,'')}/`).toString();assertLocalUrl(url);const operationId=runtime.beginOperation('api',`${endpoint.method} ${endpoint.path}`,{projectId:workspace.projectId,targetId:endpoint.id,canRetry:false,steps:['Lokale URL controleren','Request uitvoeren','Respons vastleggen']}),started=performance.now();try{runtime.updateOperation(operationId,28,'Lokale bestemming gecontroleerd.',{index:0,status:'ok',detail:url});const requestBody=['GET','HEAD'].includes(endpoint.method)?undefined:body||endpoint.requestBody||undefined,response=await fetch(url,{method:endpoint.method,headers:requestBody?{'content-type':'application/json','x-localdeck-api-studio':'1'}:{'x-localdeck-api-studio':'1'},body:requestBody,redirect:'manual',signal:AbortSignal.timeout(20_000)}),responseText=(await response.text()).slice(0,64_000),durationMs=Math.round(performance.now()-started);runtime.updateOperation(operationId,72,'Request uitgevoerd.',{index:1,status:response.status<400?'ok':'warning',detail:`HTTP ${response.status} · ${durationMs} ms.`});runtime.recordApiRun({workspaceId,endpointId,method:endpoint.method,url,status:response.status,durationMs,responsePreview:responseText});runtime.updateOperation(operationId,94,'Respons lokaal opgeslagen.',{index:2,status:'ok',detail:`${responseText.length} tekens bewaard.`});runtime.completeOperation(operationId,`HTTP ${response.status} in ${durationMs} ms.`);return runtime.snapshot()}catch(error){const durationMs=Math.round(performance.now()-started),message=error instanceof Error?error.message:String(error);runtime.recordApiRun({workspaceId,endpointId,method:endpoint.method,url,durationMs,responsePreview:'',error:message});runtime.completeOperation(operationId,message,'failed');throw error}}
async function replayWebhook(eventId:string,targetUrl:string){const event=runtime.snapshot().webhookEvents.find(item=>item.id===eventId);if(!event)throw new Error('Webhookevent niet gevonden.');const url=assertLocalUrl(targetUrl),headers=Object.fromEntries(Object.entries(event.headers).filter(([key])=>!['host','content-length','authorization','cookie'].includes(key.toLowerCase()))),response=await fetch(url,{method:event.method,headers:{...headers,'x-localdeck-replay':'1'},body:['GET','HEAD'].includes(event.method.toUpperCase())?undefined:event.body,redirect:'manual',signal:AbortSignal.timeout(20_000)});runtime.markWebhookReplayed(eventId);runtime.setUpdate({});if(response.status>=500)throw new Error(`Replaybestemming antwoordde met HTTP ${response.status}.`);return runtime.snapshot()}
async function replayCapture(id:string){const capture=runtime.snapshot().replayCaptures.find(item=>item.id===id);if(!capture)throw new Error('Replay-opname niet gevonden.');const url=assertLocalUrl(capture.url),started=performance.now(),response=await fetch(url,{method:capture.method,headers:{...capture.headers,'x-localdeck-replay':'1'},body:['GET','HEAD'].includes(capture.method.toUpperCase())?undefined:capture.body,redirect:'manual',signal:AbortSignal.timeout(20_000)}),durationMs=Math.round(performance.now()-started);runtime.markReplayCapture(id,{status:response.status,durationMs});return runtime.snapshot()}

function createWindow(){
 const screenshotArgument=process.argv.find(argument=>argument.startsWith('--localdeck-screenshot='));win=new BrowserWindow({width:1420,height:920,minWidth:1050,minHeight:700,show:false,backgroundColor:'#0b0d12',titleBarStyle:'hidden',titleBarOverlay:{color:'#0b0d12',symbolColor:'#aab1c0',height:44},webPreferences:{preload:path.join(__dirname,'preload.js'),contextIsolation:true,nodeIntegration:false,sandbox:true}});
 if(screenshotArgument){const destination=screenshotArgument.slice('--localdeck-screenshot='.length),delayArgument=process.argv.find(argument=>argument.startsWith('--localdeck-screenshot-delay=')),delay=Math.max(500,Number(delayArgument?.split('=')[1])||1600);win.webContents.once('did-finish-load',()=>setTimeout(async()=>{if(win)writeFileSync(destination,(await win.webContents.capturePage()).toPNG());quitting=true;app.quit()},delay))}else win.once('ready-to-show',()=>win?.show());
 const dev=process.env.VITE_DEV_SERVER_URL,pageArgument=process.argv.find(argument=>argument.startsWith('--localdeck-page='))?.slice('--localdeck-page='.length);if(dev)void win.loadURL(`${dev}${pageArgument?`?page=${encodeURIComponent(pageArgument)}`:''}`);else void win.loadFile(path.join(__dirname,'../dist/index.html'),pageArgument?{query:{page:pageArgument}}:undefined);
 win.webContents.setWindowOpenHandler(({url})=>{if(/^https?:/.test(url))void shell.openExternal(url);return{action:'deny'}});
 win.on('close',event=>{if(!quitting&&runtime.snapshot().settings.minimizeToTray){event.preventDefault();win?.hide()}});
}

function createTray(){
 const iconPath=app.isPackaged?path.join(process.resourcesPath,'icon.ico'):path.join(__dirname,'../build/icon.ico');
 tray=new Tray(nativeImage.createFromPath(iconPath));tray.setToolTip('LocalDeck');
 tray.setContextMenu(Menu.buildFromTemplate([{label:'LocalDeck openen',click:()=>{win?.show();win?.focus()}},{label:'Webbeheer openen',click:()=>void openWebControl()},{type:'separator'},{label:'Alles starten',click:()=>void toggleAll(true)},{label:'Alles stoppen',click:()=>void toggleAll(false)},{type:'separator'},{label:'Afsluiten',click:()=>{quitting=true;app.quit()}}]));
 tray.on('double-click',()=>win?.show());
}

async function startEmbeddedWebControl(){
 if(webServer||!runtime.snapshot().settings.webControlEnabled||runtime.snapshot().settings.runtimeMode==='windows-service'&&!runtime.snapshot().settings.simulationMode)return;
  try{const control=await startWebControl(runtime,packagedPath('installer','web-control'),{toggleService,toggleAll,updatePort:changeServicePort,refreshService:async()=>runtime.snapshot()});webServer=control.server;runtime.setUpdate({});}
 catch(error){runtime.setUpdate({});console.warn('Webbeheer kon niet starten:',error)}
}

function stopEmbeddedWebControl(){if(webServer){webServer.close();webServer=null}}
async function startEmbeddedDns(){if(dnsServer||runtime.snapshot().settings.dnsMode!=='local-dns'||runtime.snapshot().settings.runtimeMode!=='application')return;dnsServer=await startLocalDns(runtime.snapshot().settings.dataDirectory)}
function stopEmbeddedDns(){dnsServer?.close();dnsServer=null}
async function openWebControl(page='/'){const settings=runtime.snapshot().settings,token=getWebControlToken(settings.dataDirectory),safePage=page==='/mail'?'/mail':'/';await shell.openExternal(`http://127.0.0.1:${settings.webControlPort}${safePage}?token=${encodeURIComponent(token)}`);return runtime.snapshot()}

async function setRuntimeMode(mode:RuntimeMode){
 const state=runtime.snapshot();if(state.settings.runtimeMode===mode)return state;if(state.installation.status!=='installed'||state.settings.simulationMode)return runtime.setRuntimeMode(mode);
 if(mode==='windows-service'){
  await runtime.toggleAll(false);runtime.setRuntimeMode(mode);stopEmbeddedWebControl();stopEmbeddedDns();
  try{return await serviceCommand('Install')}catch(error){runtime.setRuntimeMode('application');await startEmbeddedWebControl();throw error}
 }
 await serviceCommand('Uninstall');runtime.setRuntimeMode('application');await startEmbeddedWebControl();await startEmbeddedDns();return runtime.refreshServiceStates();
}

async function checkUpdates(manual=false){
 const settings=runtime.snapshot().settings,feed=settings.updateFeedUrl||process.env.LOCALDECK_UPDATE_URL||'';
 if(!feed){if(manual)return runtime.setUpdate({status:'error',error:'Stel eerst een updatefeed-URL in bij Instellingen.',checkedAt:new Date().toISOString(),showPopup:true});return runtime.snapshot()}
 runtime.setUpdate({status:'checking',error:undefined,showPopup:false});
 try{const manifest=await fetchUpdateManifest(feed,settings.updateChannel,net.fetch),rollback={rollbackVersion:manifest.rollbackVersion,rollbackUrl:manifest.rollbackUrl,rollbackSha256:manifest.rollbackSha256},trust={signed:manifest.signed,publisher:manifest.publisher};return runtime.setUpdate(compareVersions(manifest.version,app.getVersion())>0?{status:'available',latestVersion:manifest.version,title:manifest.title||`LocalDeck ${manifest.version}`,notes:manifest.notes,downloadUrl:manifest.downloadUrl,sha256:manifest.sha256,publishedAt:manifest.publishedAt,...trust,...rollback,checkedAt:new Date().toISOString(),error:undefined,showPopup:true}:{status:'current',latestVersion:manifest.version,...trust,...rollback,checkedAt:new Date().toISOString(),error:undefined,showPopup:manual})}
 catch(error){return runtime.setUpdate({status:'error',error:error instanceof Error?error.message:String(error),checkedAt:new Date().toISOString(),showPopup:manual})}
}

async function downloadVerifiedInstaller(url:string,sha256:string|undefined,fallbackName:string,forceSignature=false,destinationDirectory=app.getPath('downloads')){const response=await net.fetch(url);if(!response.ok)throw new Error(`Download mislukt met status ${response.status}.`);const bytes=Buffer.from(await response.arrayBuffer()),hash=createHash('sha256').update(bytes).digest('hex').toUpperCase(),urlName=path.basename(new URL(url).pathname),name=urlName.toLowerCase().endsWith('.exe')?urlName:fallbackName;mkdirSync(destinationDirectory,{recursive:true});const destination=path.join(destinationDirectory,name);writeFileSync(destination,bytes);if(sha256&&hash!==sha256.toUpperCase()){unlinkSync(destination);throw new Error('De SHA-256-controle is mislukt. Het bestand is verwijderd.')}const settings=runtime.snapshot().settings;if(settings.requireSignedUpdates||forceSignature)try{await runPowerShell(installerScript('verify-update.ps1'),['-File',destination,'-Publisher',settings.trustedUpdatePublisher])}catch(error){unlinkSync(destination);throw new Error(`De updatehandtekening is afgekeurd en het bestand is verwijderd. ${error instanceof Error?error.message:String(error)}`)}return destination}

